_choice_key() {
    gsettings list-keys "$argc_schema" 2>/dev/null
}

_choice_schema() {
    _argc_util_mode_kv :
    if [[ -z "$argc__kv_prefix" ]]; then
        gsettings list-schemas
        gsettings list-relocatable-schemas | _argc_util_transform suffix=: nospace
    fi
}

_choice_value() {
    [[ -n "$argc_schema" && -n "$argc_key" ]] || return 0
    gsettings range "$argc_schema" "$argc_key" 2>/dev/null | gawk '
        NR == 1 {
            kind = $0
            if (kind == "type b") {
                print "true"
                print "false"
            }
            next
        }
        kind == "enum" || kind == "flags" {
            if ($0 ~ /^\047.*\047$/) {
                sub(/^\047/, "")
                sub(/\047$/, "")
                print
            }
        }
    '
}
